using System.Text;

namespace DependencyNavigator;

/// <summary>
/// Writes the project-level architecture as a text file that a person or an AI can read
/// without the viewer.
/// </summary>
public static class OverviewWriter
{
	public static string CreateOverview(DependencyModel model)
	{
		var text = new StringBuilder();

		text.AppendLine("# Architecture overview");
		text.AppendLine();
		text.AppendLine(
			"This file is generated by `dotnet-dependency-navigator`. " +
			"Do not edit it by hand.");
		text.AppendLine(
			"It lists every C# project of the repository with the projects it references " +
			"directly. The tiers come from the tier rules file.");
		text.AppendLine(
			"The types of each project and the types they reference are listed in " +
			"`projects/<project name>.md`.");
		text.AppendLine();
		text.AppendLine(
			$"Generated {model.Generated}: {model.Projects.Count} projects, " +
			$"{model.References.Count} project references.");

		AppendGroupDependencies(text, model, "Top-level directories",
		                        project => project.TopLevelDirectory);
		AppendGroupDependencies(text, model, "Tiers", project => project.Tier);
		AppendProjects(text, model);

		return text.ToString();
	}

	/// <summary>
	/// Lists the types of one project with the types of other projects that they reference.
	/// </summary>
	public static string CreateProjectOverview(DependencyModel model, int projectIndex)
	{
		ProjectNode project = model.Projects[projectIndex];

		ILookup<int, int[]> referencesFrom =
			model.TypeReferences.ToLookup(reference => reference[0]);
		ILookup<int, int[]> referencesTo =
			model.TypeReferences.ToLookup(reference => reference[1]);

		var text = new StringBuilder();

		text.AppendLine($"# {project.Name}");
		text.AppendLine();
		text.AppendLine(
			"This file is generated by `dotnet-dependency-navigator`. " +
			"Do not edit it by hand.");
		text.AppendLine();
		text.AppendLine($"- Project file: `{project.Path}`");
		text.AppendLine($"- Top-level directory: {project.TopLevelDirectory}");
		text.AppendLine($"- Tier: {project.Tier}");
		text.AppendLine(
			"- References the projects: " +
			JoinOrNone(model.References.Where(reference => reference[0] == projectIndex)
			                .Select(reference => model.Projects[reference[1]].Name)));
		text.AppendLine(
			"- Is referenced by the projects: " +
			JoinOrNone(model.References.Where(reference => reference[1] == projectIndex)
			                .Select(reference => model.Projects[reference[0]].Name)));

		var typesOfProject = model.Types.Select((type, index) => (type, index))
		                          .Where(item => item.type.Project == projectIndex);

		foreach (var typesOfNamespace in typesOfProject.GroupBy(item => item.type.Namespace)
		                                               .OrderBy(group => group.Key))
		{
			text.AppendLine();
			text.AppendLine($"## Namespace {typesOfNamespace.Key}");
			text.AppendLine();

			foreach ((TypeNode type, int typeIndex) in
			         typesOfNamespace.OrderBy(item => item.type.Name))
			{
				text.Append($"- {type.Kind} `{type.Name}` (`{type.File}:{type.Line}`)");

				AppendReferencedTypes(TypeReferenceKind.Inherits, "inherits", false);
				AppendReferencedTypes(TypeReferenceKind.Implements, "implements", false);
				AppendReferencedTypes(TypeReferenceKind.Uses, "uses from other projects", true);

				int usingProjectCount =
					referencesTo[typeIndex]
						.Select(reference => model.Types[reference[0]].Project)
						.Where(usingProjectIndex => usingProjectIndex != projectIndex)
						.Distinct()
						.Count();

				if (usingProjectCount > 0)
				{
					text.Append($"; used by {usingProjectCount} other projects");
				}

				text.AppendLine();

				void AppendReferencedTypes(TypeReferenceKind kind,
				                           string label,
				                           bool otherProjectsOnly)
				{
					string names = string.Join(
						", ",
						referencesFrom[typeIndex]
							.Where(reference => reference[2] == (int) kind)
							.Select(reference => model.Types[reference[1]])
							.Where(referenced => ! otherProjectsOnly ||
							                     referenced.Project != projectIndex)
							.Select(referenced => referenced.Name)
							.OrderBy(name => name));

					if (names.Length > 0)
					{
						text.Append($"; {label}: {names}");
					}
				}
			}
		}

		return text.ToString();
	}

	private static string JoinOrNone(IEnumerable<string> names)
	{
		string joined = string.Join(", ", names.OrderBy(name => name));

		return joined.Length == 0 ? "none" : joined;
	}

	private static void AppendGroupDependencies(StringBuilder text,
	                                            DependencyModel model,
	                                            string title,
	                                            Func<ProjectNode, string> getGroupName)
	{
		text.AppendLine();
		text.AppendLine($"## {title}");
		text.AppendLine();
		text.AppendLine(
			"The number in brackets is the number of project references to that group.");
		text.AppendLine();

		List<string> tierNames = model.Tiers.ToList();

		// Tiers appear in the order of the tier rules file, top-level directories in the order found.
		foreach (IGrouping<string, ProjectNode> group in
		         model.Projects.GroupBy(getGroupName)
		              .OrderBy(group => tierNames.IndexOf(group.Key)))
		{
			IEnumerable<string> usedGroups =
				model.References
				     .Where(reference => getGroupName(model.Projects[reference[0]]) == group.Key)
				     .Select(reference => getGroupName(model.Projects[reference[1]]))
				     .Where(usedGroupName => usedGroupName != group.Key)
				     .GroupBy(usedGroupName => usedGroupName)
				     .OrderByDescending(usedGroup => usedGroup.Count())
				     .Select(usedGroup => $"{usedGroup.Key} ({usedGroup.Count()})");

			string uses = string.Join(", ", usedGroups);

			text.AppendLine(
				$"- **{group.Key}** ({group.Count()} projects) uses: " +
				(uses.Length == 0 ? "nothing outside itself" : uses));
		}
	}

	private static void AppendProjects(StringBuilder text, DependencyModel model)
	{
		ILookup<int, int> usedIndexes =
			model.References.ToLookup(reference => reference[0], reference => reference[1]);
		ILookup<int, int> usedByIndexes =
			model.References.ToLookup(reference => reference[1], reference => reference[0]);

		text.AppendLine();
		text.AppendLine("## Projects");

		var indexedProjects = model.Projects.Select((project, index) => (project, index));

		foreach (var topLevelDirectory in
		         indexedProjects.GroupBy(item => item.project.TopLevelDirectory))
		{
			text.AppendLine();
			text.AppendLine($"### {topLevelDirectory.Key}");

			foreach (string tierName in model.Tiers)
			{
				var tierProjects =
					topLevelDirectory.Where(item => item.project.Tier == tierName).ToList();

				if (tierProjects.Count == 0)
				{
					continue;
				}

				text.AppendLine();
				text.AppendLine($"#### {topLevelDirectory.Key}: {tierName}");
				text.AppendLine();

				foreach ((ProjectNode project, int index) in tierProjects)
				{
					IEnumerable<string> usedNames =
						usedIndexes[index].Select(usedIndex => model.Projects[usedIndex].Name)
						                  .OrderBy(name => name);

					string uses = string.Join(", ", usedNames);

					text.AppendLine(
						$"- `{project.Name}` (used by {usedByIndexes[index].Count()} projects) " +
						(uses.Length == 0 ? "uses no other project" : $"uses: {uses}"));
				}
			}
		}
	}
}
